stamp, versión términos/cronograma y contexto medio de pago. Backend informa requisito RECURRING_AUTODEBIT_AUTH_REQUIRED; frontend no infiere por nombre. Pago único no exige esta autorización; no habilitar cuotas manuales. Sustituye CARD_ONLY y prohibición Yape histórica por elegibilidad de proveedor gobernada, sin activar Yape sin recurrencia acreditada. Binding runtime pendiente. No modifica IG, ledger, proveedores ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/521","solicitante":"Cristhian / Claude S22-AQ"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"aq_installment_autodebit_gate"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"aq_installment_missing_auth"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"aq_auth_prechecked"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_auth_not_explicit"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_auth_after_initial_payment"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_auth_evidence_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_frontend_infers_auth"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_pay_only_requires_auth"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aq_manual_installment_allowed"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"aq_installment_autodebit_gate":true,"aq_installment_missing_auth":false,"aq_auth_prechecked":false,"aq_auth_not_explicit":false,"aq_auth_after_initial_payment":false,"aq_auth_evidence_missing":false,"aq_frontend_infers_auth":false,"aq_pay_only_requires_auth":false,"aq_manual_installment_allowed":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"aq_installment_autodebit_gate":true,"aq_installment_missing_auth":true,"aq_auth_prechecked":false,"aq_auth_not_explicit":false,"aq_auth_after_i